// The mind map drawn by jsMind.
//
// The classic one: nodes in boxes, branches drawn as lines, the root in the
// middle with the tree spreading left and right. It is the least like an
// editor of the three and the easiest to read at a glance, which is why it is
// worth having beside mind-elixir rather than instead of it.
//
// Two things about driving it from React. It renders into a plain element and
// keeps its own state, so the instance is built once per tree and taken down
// after - `show()` on an existing instance leaves the old nodes' colours
// behind. And its stylesheet colours nodes by a *theme class* on the
// container; the themes it ships are fixed hues that have nothing to do with
// the app's, so no theme is set and every node carries its own colour instead,
// which is also what makes the map follow light and dark.

import * as React from 'react';
import Box from '@mui/joy/Box';

import jsMind from 'jsmind';
import 'jsmind/style/jsmind.css';

import { DensityValues, MindLook, MindNode, NodeStyle, toJsMind } from '../mindmap';

export interface JsMindHandle {
    svg: () => string;
    fit: () => void;
    zoom: (by: number) => void;
    expandAll: (open: boolean) => void;
}

interface Props {
    root: MindNode;
    look: MindLook;
    colorFor: (n: MindNode) => string;
    textOn: (bg: string) => string;
    show: { status: boolean; priority: boolean; tags: boolean };
    openTo: number;
    editable: boolean;
    nodeStyle: NodeStyle;
    density: DensityValues;
    curve: boolean;
    // How the tree is laid out around the root.
    mode: 'full' | 'side';
    onPick?: (id: string) => void;
}

const JsMindMap = React.forwardRef<JsMindHandle, Props>(function JsMindMap(props, ref) {
    const hostRef = React.useRef<HTMLDivElement>(null);
    const jmRef = React.useRef<any>(null);
    const pickRef = React.useRef(props.onPick);
    pickRef.current = props.onPick;

    const { root, look, colorFor, textOn, openTo, editable, mode, nodeStyle, density, curve } = props;
    const { status, priority, tags } = props.show;

    React.useEffect(() => {
        const host = hostRef.current;
        if (!host) return;
        host.innerHTML = '';

        const data = toJsMind(root, {
            status, priority, tags, colorFor, textOn, openTo,
            style: nodeStyle, pageInk: look.text,
        });

        const jm = new (jsMind as any)({
            container: host,
            editable,
            // No theme: the themes it ships are fixed hues, and every node
            // carries its own colour so that the map follows the app instead.
            theme: null,
            mode,
            support_html: false,
            view: {
                engine: 'svg',
                hmargin: 60,
                vmargin: 40,
                line_width: 2,
                line_color: look.line,
                line_style: curve ? 'curved' : 'straight',
                draggable: editable,
                hide_scrollbars_when_draggable: false,
            },
            layout: { hspace: density.mainGapX, vspace: density.gapY, pspace: 13 },
            shortcut: { enable: true },
        });
        jm.show(data);
        jmRef.current = jm;

        // jsMind's own event is a number; 4 is "select".
        if (typeof jm.add_event_listener === 'function') {
            jm.add_event_listener((type: number, d: any) => {
                if (type === 4 && d && d.node && pickRef.current) pickRef.current(String(d.node));
            });
        }

        return () => {
            jmRef.current = null;
            host.innerHTML = '';
        };
    }, [root, look, colorFor, textOn, status, priority, tags, openTo, editable, mode,
        nodeStyle, density, curve]);

    React.useImperativeHandle(ref, () => ({
        svg: () => {
            const host = hostRef.current;
            if (!host) return '';
            const el = host.querySelector('svg');
            return el ? el.outerHTML : '';
        },
        fit: () => {
            const jm = jmRef.current;
            if (jm && typeof jm.resize === 'function') jm.resize();
            const inner = hostRef.current && hostRef.current.querySelector('.jsmind-inner');
            if (inner) {
                // Put the root back under the eye: jsMind lays the map out
                // around the centre of a canvas wider than the window.
                (inner as HTMLElement).scrollLeft =
                    ((inner as HTMLElement).scrollWidth - (inner as HTMLElement).clientWidth) / 2;
                (inner as HTMLElement).scrollTop =
                    ((inner as HTMLElement).scrollHeight - (inner as HTMLElement).clientHeight) / 2;
            }
        },
        zoom: (by: number) => {
            const jm = jmRef.current;
            if (!jm || !jm.view) return;
            if (by > 0 && typeof jm.view.zoomIn === 'function') jm.view.zoomIn();
            else if (by < 0 && typeof jm.view.zoomOut === 'function') jm.view.zoomOut();
        },
        expandAll: (open: boolean) => {
            const jm = jmRef.current;
            if (!jm) return;
            if (open && typeof jm.expand_all === 'function') jm.expand_all();
            if (!open && typeof jm.collapse_all === 'function') jm.collapse_all();
        },
    }), []);

    return (
        <Box
            ref={hostRef}
            sx={{
                width: '100%', height: '100%', minHeight: 0,
                borderRadius: 'sm', overflow: 'hidden',
                // jsMind's stylesheet is written for a light page: the node
                // text, the fold markers and the selection all assume it. The
                // nodes carry their own colours, so what is left is the ground
                // they sit on and the two small marks it draws itself.
                '& jmnodes': { background: 'transparent' },
                '& jmnode': {
                    borderRadius: density.radius,
                    boxShadow: look.dark ? '0 1px 2px rgba(0,0,0,0.45)' : '0 1px 2px rgba(16,22,26,0.12)',
                    padding: density.padding,
                    fontSize: '13px',
                    lineHeight: 1.35,
                },
                '& jmnode:hover': { boxShadow: `0 0 0 2px ${look.accent}` },
                '& jmnode.selected': { boxShadow: `0 0 0 2px ${look.accent}` },
                '& jmexpander': {
                    border: '1px solid',
                    borderColor: look.line,
                    color: look.text,
                    background: look.panel,
                    borderRadius: '50%',
                },
                '& .jsmind-inner': { background: 'transparent' },
            }}
        />
    );
});

export default JsMindMap;
